function esc(value) {
  return String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

function decodeEntities(value) {
  return String(value ?? '')
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#43;/g, '+');
}

function strip(value, size = 240) {
  return decodeEntities(value)
    .replace(/<[^>]+>/g, '')
    .replaceAll('\n', ' ')
    .replaceAll('\r', ' ')
    .replaceAll('\t', ' ')
    .trim()
    .slice(0, size);
}

function shortDate(value) {
  if (!value) return '';
  const raw = String(value);
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return raw.slice(0, 10);
  return date.toISOString().slice(0, 10);
}

function mapStatusEn(value) {
  const v = String(value || '').toLowerCase().replace(/_/g, ' ').replace(/\s+/g, ' ').trim();
  if (v === 'to do' || v === 'todo') return 'To do';
  if (v === 'in progress' || v === 'inprogress') return 'In progress';
  if (v === 'done') return 'Done';
  if (v === 'blocked') return 'Blocked';
  if (v === 'waiting on' || v === 'waitingon') return 'Waiting';
  return value || 'Unspecified';
}

function statusWithEmoji(value) {
  const v = String(value || '').toLowerCase().replace(/_/g, ' ').replace(/\s+/g, ' ').trim();
  const label = mapStatusEn(value);
  if (v === 'to do' || v === 'todo') return '📋 ' + label;
  if (v === 'in progress' || v === 'inprogress') return '🔵 ' + label;
  if (v === 'done') return '✅ ' + label;
  if (v === 'blocked') return '🚧 ' + label;
  if (v === 'waiting on' || v === 'waitingon') return '⏳ ' + label;
  return '📌 ' + label;
}

function mapPriorityEn(value) {
  const v = String(value || '').toUpperCase();
  if (v === 'HIGH') return 'High';
  if (v === 'NORMAL' || v === 'MEDIUM') return 'Normal';
  if (v === 'LOW') return 'Low';
  return value || 'Unspecified';
}

function mentionUser(value) {
  const username = String(value || '').trim();
  if (!username) return '';
  return username.startsWith('@') ? username : '@' + username;
}

function taskRef(task) {
  const id = task.task_id || task.id || '';
  if (!id) return '';
  return '/task:' + id;
}

const config = $json.config;
const template = $json.template_payload;
const taskPayload = $json.tasks_payload;
const tasks = Array.isArray(taskPayload) ? taskPayload : (taskPayload?.tasks || []);

const rows = tasks.map(task => {
  const status = task.status?.status || task.status?.name || task.status || '';
  const assignee = mentionUser(task.assignee?.username || task.assignee || task.assignee_username || '');
  const due = shortDate(task.due_date || task.end_date || task.dueDate || '');
  const priority = task.priority || '';
  const title = strip(task.title || task.name || ('Task ' + (task.task_id || task.id || '')), 120);
  const comment = task.description || task.last_comment || task.blocking_comment || '';
  return '<tr><td>' + esc(taskRef(task)) + '</td><td>' + esc(title) + '</td><td>' + esc(assignee) + '</td><td>' + esc(statusWithEmoji(status)) + '</td><td>' + esc(due) + '</td><td>' + esc(mapPriorityEn(priority)) + '</td><td>' + esc(strip(comment)) + '</td></tr>';
});

const reportHtml = rows.length
  ? '<table><thead><tr><th>Task</th><th>Subject</th><th>Owner</th><th>Status</th><th>Due</th><th>Priority</th><th>Comment / blocker</th></tr></thead><tbody>' + rows.join('') + '</tbody></table>'
  : '<p>No tasks found in the project scope at preparation time.</p>';

const statusCounts = {};
for (const task of tasks) {
  const status = String(task.status?.status || task.status?.name || task.status || 'Unspecified');
  statusCounts[status] = (statusCounts[status] || 0) + 1;
}

return [{
  json: {
    ...config,
    template_note: template,
    template_html: String(template?.html_content || ''),
    tasks,
    task_count: tasks.length,
    status_counts: statusCounts,
    report_html: reportHtml,
    ai_prompt_payload: JSON.stringify({
      meeting_date: config.meeting_date,
      thresholds: {
        stagnation_days: config.stagnation_days,
        blocked_days: config.blocked_days,
        overload_threshold: config.overload_threshold
      },
      status_counts: statusCounts,
      tasks: tasks.map(task => ({
        task_id: task.task_id || task.id,
        task_ref: taskRef(task),
        title: task.title || task.name,
        status: mapStatusEn(task.status?.status || task.status?.name || task.status),
        priority: mapPriorityEn(task.priority),
        assignee: mentionUser(task.assignee?.username || task.assignee || task.assignee_username),
        due_date: shortDate(task.due_date || task.end_date || task.dueDate),
        updated_date: task.updated_date || task.updatedDate,
        description: strip(task.description)
      }))
    })
  }
}];
